// Parse and validate one finished game. Junk or tampered payloads are dropped.
const out = [];
for (const item of $input.all()) {
  let data = null;
  const body = item.json.body;
  if (body && typeof body === 'object' && 'score' in body) {
    data = body;
  } else if (typeof body === 'string') {
    try { data = JSON.parse(body); } catch (e) {}
  }
  if (!data && item.binary && item.binary.data) {
    try { data = JSON.parse(Buffer.from(item.binary.data.data, 'base64').toString('utf8')); } catch (e) {}
  }
  if (!data) continue;

  const int = (v) => Number.isInteger(v) ? v : NaN;
  const score = int(data.score);
  const found = int(data.found);
  const falseAlarms = int(data.falseAlarms);
  const seconds = int(data.seconds);
  const missed = Array.isArray(data.missed) ? data.missed : null;

  const ok =
    score >= 0 && score <= 1500 &&
    found >= 0 && found <= 12 &&
    falseAlarms >= 0 && falseAlarms <= 4 &&
    seconds >= 0 && seconds <= 86400 &&
    missed !== null &&
    missed.length === 12 - found &&
    missed.every(n => Number.isInteger(n) && n >= 1 && n <= 12) &&
    new Set(missed).size === missed.length;
  if (!ok) continue;

  const received = new Date().toLocaleString('en-US', { timeZone: 'America/Los_Angeles', hour12: false });
  out.push({ json: {
    'Received': received,
    'Score': score,
    'Flags found': found,
    'False alarms': falseAlarms,
    'Seconds': seconds,
    'Missed flags': missed.length ? ',' + missed.sort((a, b) => a - b).join(',') + ',' : '',
    'Client time': typeof data.ts === 'string' ? data.ts.slice(0, 30) : '',
    'Source': data.src === 'challenge' ? 'challenge' : 'direct'
  }});
}
return out;
